validate:
(result, args, expected) => {
  const s = args[0];
  if (typeof result !== "string") return "Return a string.";
  if (result.length !== expected.length) return "Your answer has length " + result.length + ", but the longest palindromic substring has length " + expected.length + ".";
  if (!s.includes(result)) return JSON.stringify(result) + " is not a contiguous substring of the input.";
  for (let i = 0, j = result.length - 1; i < j; i++, j--) if (result[i] !== result[j]) return JSON.stringify(result) + " is not a palindrome.";
  return true;
}
